insert into tap_results select throws_ok($$select public.agri_command('save_credit_contact',pg_temp.policy(704)||'{"expectedVersion":3,"clientType":"admin"}')$$,'P0001','Choose Normal customer, Distributor or Owner','Unsupported classification rejected');
insert into tap_results select lives_ok($$select public.agri_command('supplier_create_order',pg_temp.quoted(2000))$$,'Owner records a price quote');
insert into tap_results select is(public.agri_command('purchasing_workspace',pg_temp.ctx())->'orders'->0->'commercial'->>'quotedTotal','100000','Quote total uses actual ordered units');
insert into tap_results select is((select count(*) from pg_temp.bills()),0::bigint,'Quote creates no supplier debt');
insert into tap_results select is((select count(*) from public.purchase_receipts),0::bigint,'Quote creates no receiving');
insert into tap_results select is(public.agri_command('supplier_create_order',pg_temp.quoted(2000))->>'duplicate','true','Original quote retries once');
insert into tap_results select throws_ok($$select public.agri_command('supplier_create_order',pg_temp.quoted(2002)||jsonb_build_object('commercial',jsonb_build_object('paymentMode','cash','term',0,'unitCosts',jsonb_build_object(pg_temp.i(2101)::text,30000))))$$,'P0001','This order already has its original commercial request','Another root cannot rebind a quote or break the workspace');
insert into tap_results select is(jsonb_array_length(public.agri_command('purchasing_workspace',pg_temp.ctx())->'orders'),1,'Owner workspace remains readable after rejected duplicate quote');
insert into saved values('cash',pg_temp.composite(3000,100000));
insert into tap_results select lives_ok($$select public.agri_command('supplier_receive_purchase',(select data from saved where name='cash'))$$,'Cash receiving saves stock, supplier invoice and external payment together');
insert into tap_results select is(pg_temp.sstate(3002)->>'balance','0','Cash invoice fully settled');
insert into tap_results select is(pg_temp.sstate(3002)->>'paid','100000','Cash actually paid retained');
insert into tap_results select is((select method from pg_temp.entries() where id=pg_temp.i(3003)),'owner_cash','Supplier cash comes from owner outside till');
insert into tap_results select is((select count(*) from public.payments),0::bigint,'Supplier payment never reduces sales drawer');
insert into tap_results select is((select sum(quantity) from public.inventory_movements where source_id=pg_temp.i(3001)),4::numeric,'Accepted receiving quantity added once');
insert into tap_results select is(public.agri_command('supplier_receive_purchase',(select data from saved where name='cash'))->>'duplicate','true','Lost confirmation retries original composite response');
insert into tap_results select is((select count(*) from public.purchase_receipts where id=pg_temp.i(3001)),1::bigint,'Retry does not duplicate goods');
insert into tap_results select is((select count(*) from pg_temp.entries() where bill_id=pg_temp.i(3002)),2::bigint,'Retry does not duplicate invoice or payment');
